/**
 * @summary Resolve a Bilbasen listing URL or catalog id into a Car
 */
export const getBilcostGetListingUrl = (params: BilcostGetListingParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/bilcost/listing?${stringifiedParams}`
    : `/api/bilcost/listing`;
};

export const bilcostGetListing = async (
  params: BilcostGetListingParams,
  options?: RequestInit,
): Promise<BilcostCar> => {
  return customFetch<BilcostCar>(getBilcostGetListingUrl(params), {
    ...options,
    method: "GET",
  });
};

